function markPath(pts, ch) {
  for (let i = 0; i < pts.length - 1; i++) {
    let [x, y] = pts[i];
    const [tx, ty] = pts[i+1];
    const dx = Math.sign(tx - x), dy = Math.sign(ty - y);
    while (true) {
      grid[y][x] = grid[y][x] === ' . ' ? ch : ' + ';
      if (x === tx && y === ty) break;
      x += dx; y += dy;
