  for (const e of ENEMIES) {
    if (e.firstWave <= w) {
      totW += e.weight;
      let hp = Math.floor(e.baseHp * m / 1000);
      if (e.name === 'splitter') hp += 3 * Math.max(1, Math.floor(hp/4));
      expHp += e.weight * hp;
      expBounty += e.weight * (e.bounty + (e.name === 'splitter' ? 3 : 0));
    }
